// Bài 8.4 — tìm N+1
function findNPlusOne(log, threshold = 5) {
  const counts = {};
  for (const q of log) counts[q] = (counts[q] ?? 0) + 1;
  return Object.entries(counts).filter(([, n]) => n >= threshold).map(([template, count]) => ({ template, count }));
}

